This combines your logic with the necessary setup, collision detection, and game loop.

```javascript
const grid = document.getElementById('grid');
const scoreBot1El = document.getElementById('score-bot1');
const scoreBot2El = document.getElementById('score-bot2');

// Inputs
const foodIntervalInput = document.getElementById('food-interval');
const bot1SightDistanceInput = document.getElementById('bot1-sight-distance');
const bot2SightDistanceInput = document.getElementById('bot2-sight-distance');

// Display labels for inputs
const intervalVal = document.getElementById('interval-val');
const bot1Val = document.getElementById('bot1-val');
const bot2Val = document.getElementById('bot2-val');

// Configuration
const gridSize = 20; // 20x20 grid
let foodIntervalTime = 1000;
let lastFoodTime = 0;

// State
let scoreBot1 = 0;
let scoreBot2 = 0;

// Initialize Grid CSS
grid.style.gridTemplateColumns = `repeat(${gridSize}, 20px)`;

// Create Grid Cells
const cells = [];
for (let i = 0; i < gridSize * gridSize; i++) {
    const cell = document.createElement('div');
    cell.classList.add('cell');
    grid.appendChild(cell);
    cells.push(cell);
}

// Bot Objects
const bot1 = { x: 2, y: 2, dx: 0, dy: 0, id: 'bot1', scoreEl: scoreBot1El };
const bot2 = { x: 17, y: 17, dx: 0, dy: 0, id: 'bot2', scoreEl: scoreBot2El };

// Helper: Get Cell Index
function getIndex(x, y) {
    return y * gridSize + x;
}

// Helper: Render Bots and Food
function render() {
    // Clear previous bot positions
    cells.forEach(cell => {
        cell.classList.remove('bot1', 'bot2');
    });

    // Draw Bot 1
    const idx1 = getIndex(bot1.x, bot1.y);
    if (cells[idx1]) cells[idx1].classList.add('bot1');

    // Draw Bot 2
    const idx2 = getIndex(bot2.x, bot2.y);
    if (cells[idx2]) cells[idx2].classList.add('bot2');
}

// Logic: Find Closest Food within Sight Distance
function findClosestFood(bot, sightDistance) {
    let closestFood = null;
    let minDistance = Infinity;

    for (let i = 0; i < cells.length; i++) {
        if (cells[i].classList.contains('food')) {
            const foodX = i % gridSize;
            const foodY = Math.floor(i / gridSize);

            // Manhattan Distance
            const distance = Math.abs(bot.x - foodX) + Math.abs(bot.y - foodY);

            // Check if within sight and closer than previous best
            if (distance <= sightDistance && distance < minDistance) {
                minDistance = distance;
                closestFood = { x: foodX, y: foodY };
            }
        }
    }

    return closestFood;
}

// Logic: Move Bot
function moveSmartBot(bot, sightDistance) {
    const closestFood = findClosestFood(bot, sightDistance);

    if (closestFood) {
        // Move towards food
        if (closestFood.x !== bot.x) {
            bot.dx = Math.sign(closestFood.x - bot.x);
            bot.dy = 0;
        } else if (closestFood.y !== bot.y) {
            bot.dx = 0;
            bot.dy = Math.sign(closestFood.y - bot.y);
        }
    } else {
        // Wander randomly if no food in sight
        if (Math.random() < 0.2) { // Change direction occasionally
            const directions = [
                { dx: 0, dy: -1 }, { dx: 0, dy: 1 },
                { dx: -1, dy: 0 }, { dx: 1, dy: 0 }
            ];
            const rand = directions[Math.floor(Math.random() * directions.length)];
            bot.dx = rand.dx;
            bot.dy = rand.dy;
        }
    }

    // Apply Movement with Boundary Checks
    const newX = bot.x + bot.dx;
    const newY = bot.y + bot.dy;

    if (newX >= 0 && newX < gridSize && newY >= 0 && newY < gridSize) {
        bot.x = newX;
        bot.y = newY;
    } else {
        // Hit wall, stop or bounce (here we just stop movement for simplicity)
        bot.dx = 0;
        bot.dy = 0;
    }
}

// Logic: Handle Eating
function checkCollisions() {
    [bot1, bot2].forEach(bot => {
        const idx = getIndex(bot.x, bot.y);
        if (cells[idx].classList.contains('food')) {
            cells[idx].classList.remove('food');
            bot.scoreEl.innerText = ++(bot === bot1 ? scoreBot1 : scoreBot2);
        }
    });
}

// Logic: Spawn Food
function spawnFood() {
    // Remove old food if any (optional, depending on if you want multiple foods)
    // For this demo, let's keep one food at a time
    const existingFood = document.querySelector('.food');
    if (existingFood) existingFood.classList.remove('food');

    let randomIndex;
    do {
        randomIndex = Math.floor(Math.random() * cells.length);
    } while (cells[randomIndex].classList.contains('bot1') || cells[randomIndex].classList.contains('bot2'));

    cells[randomIndex].classList.add('food');
}

// Main Loop
function gameLoop(timestamp) {
    // Handle Food Spawning
    if (timestamp - lastFoodTime > foodIntervalTime) {
        spawnFood();
        lastFoodTime = timestamp;
    }

    // Get current sight distances
    const sight1 = parseInt(bot1SightDistanceInput.value);
    const sight2 = parseInt(bot2SightDistanceInput.value);

    // Move Bots
    moveSmartBot(bot1, sight1);
    moveSmartBot(bot2, sight2);

    // Check Eating
    checkCollisions();

    // Render
    render();

    requestAnimationFrame(gameLoop);
}

// Event Listeners for UI Updates
foodIntervalInput.addEventListener('input', (e) => {
    foodIntervalTime = e.target.value * 1000;
    intervalVal.innerText = e.target.value;
});

bot1SightDistanceInput.addEventListener('input', (e) => {
    bot1Val.innerText = e.target.value;
});

bot2SightDistanceInput.addEventListener('input', (e) => {
    bot2Val.innerText = e.target.value;
});

// Start Game
spawnFood(); // Spawn initial food
requestAnimationFrame(gameLoop);
```

